// PlayInfo Everything a client needs to begin playback of one item.
type PlayInfo struct {
	// DurationMs Duration in milliseconds.
	DurationMs int64 `json:"durationMs"`

	// ExpiresAt When the embedded media token stops being accepted.
	ExpiresAt time.Time `json:"expiresAt"`

	// MimeType MIME type the stream will be served as.
	MimeType string `json:"mimeType"`

	// PartCount Number of parts in a multi-file audiobook. Present only for multi-file books; single-file items omit the part fields entirely.
	PartCount *int `json:"partCount,omitempty"`

	// PartIndex Zero-based index of the resolved part within a multi-file audiobook. Present exactly when `partCount` is.
	PartIndex *int `json:"partIndex,omitempty"`

	// PartStartMs Book-timeline millisecond offset where the resolved part begins. In-part positions plus this offset give the book-timeline positions that play-state expects. Present exactly when `partCount` is.
	PartStartMs *int64 `json:"partStartMs,omitempty"`

	// Pid The resolved item's PID.
	Pid string `json:"pid"`

	// Seekable Whether the stream supports sample-exact seeking.
	Seekable bool `json:"seekable"`

	// SpanEndMs End of the playback window in served-audio milliseconds. Present exactly when `spanStartMs` is.
	SpanEndMs *int64 `json:"spanEndMs,omitempty"`

	// SpanStartMs Present exactly with `spanEndMs`, and only when the url serves the item's whole backing file while the item is a window into it (direct playback of a track carved from a larger rip, on a server running without the streaming engine): the client must play only the [`spanStartMs`, `spanEndMs`) window of the served audio. Absent whenever the server cuts the stream itself. `durationMs` remains the item's own duration, never the backing file's.
	SpanStartMs *int64 `json:"spanStartMs,omitempty"`

	// Url Origin-relative, media-token-authenticated stream URL. Short TTL; re-request play-info on expiry or a `stream-stale` error.
	Url string `json:"url"`

	// VoiceBoost True when the stream applies server-side spoken-word loudness normalization. Absent or false otherwise, including when it was requested but cannot be applied yet (unsupported by the sidecar, or loudness not measured yet).
	VoiceBoost *bool `json:"voiceBoost,omitempty"`
}

// PlayState The calling user's playback state for one item.
type PlayState struct {
	// Finished Whether the item was completed. For multi-file audiobooks the server derives completion from the book-timeline position; a client-reported finished flag alone does not finish a book.
	Finished bool `json:"finished"`

	// Pid The item this state belongs to.
	Pid string `json:"pid"`

	// PlayCount How many times the item has been played.
	PlayCount int `json:"playCount"`

	// Played Whether the item has crossed its played threshold. The server derives this from the position reached against the item's full duration (per-medium thresholds), never from a listened-milliseconds ratio, so silence trimming and speed changes cannot distort it.
	Played bool `json:"played"`

	// PositionMs Resume position in milliseconds. For multi-file audiobooks this is always a book-timeline position spanning all parts.
	PositionMs int64 `json:"positionMs"`

	// Rating The caller's rating (0 to 100); absent or null when unrated.
	Rating *int `json:"rating,omitempty"`

	// Starred Whether the caller starred the item.
	Starred bool `json:"starred"`

	// UpdatedAt When this state last changed.
	UpdatedAt *time.Time `json:"updatedAt,omitempty"`
}

// PlayStateList The caller's playback states for a requested batch.
type PlayStateList struct {
	// States One entry per requested item with recorded state; items with zero state are absent.
	States []PlayState `json:"states"`
}

// PlayStateQuery A batch play-state read request.
type PlayStateQuery struct {
	// Pids Items to read the caller's state for.
	Pids []string `json:"pids"`
}

// PlayStateUpdate A resume-position checkpoint.
type PlayStateUpdate struct {
	// PositionMs Playback position in milliseconds. For multi-file audiobooks always a book-timeline position (play-info's `partStartMs` plus the in-part position).
	PositionMs int64 `json:"positionMs"`

	// RecordedAt When the checkpoint was recorded on the client, sent only when replaying an offline queue. The server reconciles replays per medium: audiobooks and long tracks are recency-primary (the most recently recorded position wins, so a stale replay never drags a 14-hour book backward or forward), while music and podcast episodes are furthest-position-wins with a recency guard (the further position wins unless the nearer one is substantially more recent, honoring a deliberate rewind). Future-dated values are clamped to the server clock. Live checkpoints omit it and always apply. The response does not reveal whether a replay was applied or skipped: after flushing an offline queue, clients learn the winning state through `/sync/server` (a skipped replay means the winner is already in the event stream).
	RecordedAt *time.Time `json:"recordedAt,omitempty"`
}

// PlaybackSession One playback session: a queue playing (or paused) on an endpoint. `positionMs` is the position that was true at `positionAt` (server clock); while `playing`, controllers extrapolate forward with `rate`. `authority` says who advances playback: `remote` sessions are driven by the server (cast, DLNA, jukebox), `mirror` sessions are driven by the playing client and mirrored here. Both are controlled the same way.
type PlaybackSession struct {
	// Authority `remote` or `mirror` (open string).
	Authority string `json:"authority"`

	// Ended Present true only over the WebSocket, and terminal for that delivery context: the watched or reported session ended, or left the receiver's visibility (a transfer to a private endpoint). Re-list `/player/sessions` to learn which. Never true from the REST endpoints, which answer `not-found` for sessions the caller cannot see.
	Ended *bool `json:"ended,omitempty"`

	// EndpointId The endpoint the session plays on.
	EndpointId string `json:"endpointId"`

	// EndpointName The endpoint's display name, for one-call rendering.
	EndpointName *string `json:"endpointName,omitempty"`

	// Entries The queue, in play order. Always present on the REST endpoints. WebSocket `session` frames carry it on the first frame of a watch and whenever `queueVersion` bumped, and omit it otherwise (absent means unchanged since the version you last saw; refetch the session if you lost track).
	Entries *[]PlaybackSessionEntry `json:"entries,omitempty"`

	// Id Session PID. Stable across transfers between endpoints.
	Id string `json:"id"`

	// Index Zero-based index of the current entry.
	Index int `json:"index"`

	// Mine True when the caller owns the session.
	Mine bool `json:"mine"`

	// OwnerName The owning user's display name. Present on sessions the caller does not own (it is how a shared speaker's UI says who is playing).
	OwnerName *string `json:"ownerName,omitempty"`

	// Playing Whether playback is running right now.
	Playing bool `json:"playing"`

	// PositionAt Server-clock instant `positionMs` was true, millisecond precision. Extrapolate against the WebSocket clock offset.
	PositionAt time.Time `json:"positionAt"`

	// PositionMs Position within the current entry at `positionAt`.
	PositionMs int64 `json:"positionMs"`

	// QueueVersion The server-owned queue generation, monotone per session id across transfers and authority changes: it bumps whenever the queue (entries or their order) changes. A playing client's reported version is only an edge signal; the published value here is the server's.
	QueueVersion int64 `json:"queueVersion"`

	// Rate Playback rate. 1.0 is normal speed.
	Rate float64 `json:"rate"`

	// Repeat `off`, `all`, or `one` (open string).
	Repeat *string `json:"repeat,omitempty"`

	// Shuffle Whether shuffle is on. `entries` always lists the true play order: turning shuffle on reorders the unplayed remainder (and bumps `queueVersion`); turning it off keeps the current order.
	Shuffle *bool `json:"shuffle,omitempty"`

	// UpdatedAt Last state change (position ticks included).
	UpdatedAt time.Time `json:"updatedAt"`

	// Volume Endpoint volume, 0 to 1. Absent on endpoints without volume control.
	Volume *float64 `json:"volume,omitempty"`
}

